import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 57 · everyday recipe: creamy potato soup (Google Trends 3/11: best soup recipes rising)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, when I was a girl, potato soup was what we ate on Thursday, the day before payday, when there was nothing left in the house but a sack of potatoes, an onion, and a little milk. And it was the best night of the week. My mother made it in a big dented pot, and we ate it with saltine crackers crumbled on top until the bowls were scraped clean.""",
   "creamy potato soup bowl crackers", "THE DAY BEFORE PAYDAY")
sc("""But people tell me their potato soup comes out like wallpaper glue, or thin and watery, or it tastes like boiled nothing. So tonight I'm giving you my mother's potato soup, every step, and the five mistakes that make it gluey and bland. And stay with me, because the last trick is how to make it thick and creamy without any flour at all.""",
   "gluey thick potato soup spoon", "LIKE WALLPAPER GLUE")

ch("Thursday soup")
sc("""My father worked at the Westinghouse plant in Mansfield, and he got paid on Friday. By Thursday, my mother had stretched every dollar as far as it would go. So Thursday was potato soup. She said a good cook could feed a family of four on fifty cents and a little imagination. She had a lot of imagination, honey.""",
   "1950s factory workers Ohio", "FIFTY CENTS AND IMAGINATION")
sc("""When I grew up, I found out other families called potato soup poor man's soup, and they were a little ashamed of it. We never were. My father said it was the only soup that made him feel rich. And when I got married, the first thing my husband asked me to learn was my mother's potato soup. In a minute I'll tell you why hers was better than everybody else's.""",
   "family eating soup kitchen table 1950s", "IT MADE HIM FEEL RICH")
sc("""And today, honey, it's still one of the cheapest suppers there is. A pot that feeds six costs about eight dollars, even with bacon and cheese on top. It's ready in forty minutes. And it's the perfect supper for a cold, gray night in November, when everybody's tired and nobody wants to cook.""",
   "pot of soup stove cold night", "ABOUT EIGHT DOLLARS")

ch("What you need")
sc("""Here's what you need, honey. Three pounds of potatoes, about six or seven medium ones. Four slices of bacon. One onion, chopped. Two ribs of celery, chopped. Two cloves of garlic. Four cups of chicken broth. One and a half cups of whole milk or half and half. Two tablespoons of butter. Salt, pepper, and a little fresh thyme or a bay leaf. And for the top, cheddar cheese, chives, and sour cream.""",
   "potatoes bacon onion celery broth", "THE INGREDIENTS")
sc("""And here's mistake number one, and it's the reason most potato soup tastes like glue. The wrong potato. Russet potatoes, the big brown baking kind, are very starchy, and they fall apart into paste. Yukon Gold potatoes, the yellow ones, are creamy and buttery and hold together better. My mother used whatever was cheapest, but when she could, she used the yellow ones.""",
   "yukon gold russet potatoes", "THE WRONG POTATO")
sc("""Or, honey, use half and half. Half Yukon Gold for the creamy body, and half russet, because they break down a little and thicken the soup naturally. That's what I do now. Peel them or leave the skins on, it's up to you. My mother always peeled them and gave the peels to Mrs. Kowalski's chickens.""",
   "peeling potatoes kitchen sink", "HALF AND HALF")

ch("The base")
sc("""Step one. Chop the bacon and cook it slowly in a big heavy pot over medium heat, until it's crisp. Lift it out with a spoon and set it on a paper towel for the top. Leave about two tablespoons of the bacon fat in the pot. Add the butter, the onion and the celery, and cook them for about eight minutes, until they're soft and sweet. Then the garlic, for one minute.""",
   "bacon frying pot onion celery", "SOFT AND SWEET")
sc("""And here's mistake number two. Skipping that step, and boiling the onion with the potatoes. Raw boiled onion tastes sharp and flat. Onions cooked slowly in bacon fat and butter turn sweet and golden, and they give the whole soup its deep flavor. That's my mother's first secret. Every good soup starts in the fat, she said.""",
   "golden onions cooking butter", "IT STARTS IN THE FAT")

ch("The potatoes")
sc("""Step two. Cut the potatoes into even chunks, about three quarters of an inch. Mistake number three is uneven pieces. The little ones turn to mush while the big ones are still hard. Even pieces cook evenly. Add them to the pot, with the broth, the thyme or bay leaf, and a teaspoon of salt. The broth should just cover the potatoes.""",
   "cubed potatoes cutting board even", "EVEN PIECES")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. Bring it to a boil, then turn it down and let it simmer, partly covered, for about fifteen to twenty minutes, until a fork slides through a potato chunk easily. Don't boil it hard, or the outside of the potatoes falls apart before the inside is cooked.""",
   "potatoes simmering broth pot", "UNTIL A FORK SLIDES IN")

ch("Thick without flour")
sc("""So far, the right potatoes, onions cooked slow in bacon fat, even pieces, and a gentle simmer. Now the trick I promised you, how to make it thick without any flour. Take out the bay leaf. Then take a potato masher, and mash about a third of the potatoes right there in the pot, leaving the rest in chunks. The mashed potato thickens the soup naturally, and you still have pieces to bite.""",
   "potato masher in soup pot", "MASH A THIRD")
sc("""And here's mistake number four, the other reason soup turns to glue. Using a blender or a food processor on the whole pot. The fast blades break open the potato starch, and it turns into a sticky, gummy paste. If you want it smooth, use a hand masher, or blend only a cup or two, gently. My mother didn't own a blender, and her soup was never once gluey.""",
   "gluey blended potato soup", "NO BLENDER")
sc("""Step three. Turn the heat down to low, and stir in the milk or half and half. And mistake number five. Boiling the soup after the milk goes in. Milk can curdle and separate when it boils, and you get little white flecks. Keep it on low, just until it's hot and steaming. Then taste it, and add salt and pepper. Potatoes need a lot of salt, honey. Taste it twice.""",
   "pouring milk into soup low heat", "DON'T BOIL THE MILK")

sc("""And my mother had one more trick, honey, for a soup with real depth. A tiny splash of vinegar or a squeeze of lemon right at the end, just a teaspoon in the whole pot. You can't taste it, but it wakes up all the flavors, the way a little salt does. My father always said her soup tasted better than anybody's, and he never knew about the vinegar. She took that secret all the way to nineteen ninety-eight.""",
   "teaspoon vinegar soup pot", "A SECRET SPLASH")

ch("The toppings")
sc("""Ladle it into big bowls, and now the best part. Pile the toppings on. A handful of shredded sharp cheddar, the crumbled bacon, a spoon of sour cream, and some chopped chives or green onion. It's like a loaded baked potato in a bowl. My grandchildren call it baked potato soup, and they put so much cheese on, you can't see the soup.""",
   "potato soup cheese bacon chives", "LOADED BAKED POTATO")
sc("""And my mother's way, sweetheart, on Thursdays, when there was no bacon or cheese. A handful of saltine crackers crumbled on top, a pat of butter melting in the middle, and a good shake of black pepper. That's all. And honestly, some nights, that's still how I like it best. It tastes like Elm Street.""",
   "saltine crackers butter soup bowl", "IT TASTES LIKE ELM STREET")

ch("Making it your own")
sc("""You can make this soup a hundred ways. Add a cup of corn and some diced ham, and it's a potato chowder. Add broccoli florets for the last ten minutes, and stir in cheddar at the end for broccoli cheese potato soup. Or leave out the bacon, use vegetable broth, and add leeks, for a lighter soup. Linda makes it with smoked sausage on Sundays.""",
   "potato chowder corn ham", "A HUNDRED WAYS")
sc("""And if it's too thick, add a splash of broth or milk. If it's too thin, mash a few more potatoes, or let it simmer uncovered a few minutes. Remember, potato soup always gets thicker as it sits. So make it a little thinner than you want it in the pot, and by the time it's in the bowls, it'll be just right.""",
   "stirring thick soup ladle", "IT GETS THICKER")

sc("""And serve it with something warm on the side, sweetheart. A pan of cornbread, or buttered toast, or grilled cheese sandwiches cut in triangles for the children to dip. My grandson calls grilled cheese and potato soup the best supper in America, and I can't argue with him. It costs about a dollar a person, and nobody leaves the table hungry.""",
   "grilled cheese soup dipping", "THE BEST SUPPER IN AMERICA")

ch("Keeping")
sc("""It keeps four days in the icebox. When you warm it up, it'll be very thick, so add a little milk or broth and heat it gently, stirring, never boiling. And here's something people don't know. Potato soup with milk in it doesn't freeze well. The potatoes turn grainy. If you want to freeze it, freeze it before you add the milk, and add the milk when you warm it up.""",
   "soup containers refrigerator", "FREEZE IT BEFORE THE MILK")

ch("Grandma's kitchen")
sc("""So one more time. Yukon Gold potatoes, or half and half with russet. Onion and celery cooked slow in bacon fat and butter. Even pieces. A gentle simmer. Mash a third of the potatoes, by hand, no blender. Milk on low, never boiling. Plenty of salt. And pile on the toppings. That's my mother's Thursday potato soup, and it's never gluey.""",
   "potato soup family supper table", "NEVER GLUEY")
sc("""Tell me in the comments, sweetheart. What did your family eat the day before payday? I bet a lot of you had potato soup too. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey.""",
   "warm kitchen evening soup pot", "THE DAY BEFORE PAYDAY?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma57", "Potato Soup EVERYONE's Grandma Made (Why Yours Is GLUEY)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Starch in potatoes: high-starch russets break down and turn gummy when overworked; waxy and all-purpose Yukon Golds stay creamy.",
      "Recipe as written by Grandma Ruth: 3 lb potatoes, 4 slices bacon, 1 onion, 2 celery ribs, 2 garlic cloves, 4 cups chicken broth, 1 1/2 cups whole milk or half and half, 2 tbsp butter, thyme or bay leaf; simmer 15 to 20 minutes, mash a third by hand."],
     "everyday recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
